import { test, describe } from 'node:test';
import assert from 'node:assert/strict';

import { eventsForBooking } from '../src/store/eventStore.ts';
import type { DomainEvent } from '../src/domain/events.ts';

function requested(bookingId: string, occurredAt: string): DomainEvent {
  return {
    type: 'BookingRequested', bookingId, occurredAt, actorId: 'u-pat',
    userId: 'u-pat', userRole: 'STUDENT', resourceId: 'gpu-a100-01',
    startAt: '2026-08-05T09:00:00.000Z', endAt: '2026-08-05T13:00:00.000Z',
    requiresApproval: false,
  } as DomainEvent;
}

function approved(bookingId: string, occurredAt: string): DomainEvent {
  return { type: 'BookingApproved', bookingId, occurredAt, actorId: 'u-admin' } as DomainEvent;
}

function started(bookingId: string, occurredAt: string): DomainEvent {
  return { type: 'BookingStarted', bookingId, occurredAt, actorId: 'u-pat', actualStartAt: occurredAt } as DomainEvent;
}

describe('ประวัติการจอง (REQ-41)', () => {
  test('คืนเฉพาะเหตุการณ์ของการจองที่ระบุ', () => {
    const events = [
      requested('bk-1', '2026-08-01T00:00:00.000Z'),
      requested('bk-2', '2026-08-01T00:00:00.000Z'),
      approved('bk-1', '2026-08-02T00:00:00.000Z'),
    ];
    const history = eventsForBooking(events, 'bk-1');
    assert.equal(history.length, 2);
    assert.ok(history.every((e) => e.bookingId === 'bk-1'));
  });

  test('เรียงตามเวลาที่เกิดเหตุการณ์ แม้ลำดับที่บันทึกจะสลับกัน', () => {
    const events = [
      started('bk-1', '2026-08-03T00:00:00.000Z'),
      requested('bk-1', '2026-08-01T00:00:00.000Z'),
      approved('bk-1', '2026-08-02T00:00:00.000Z'),
    ];
    const history = eventsForBooking(events, 'bk-1');
    assert.deepEqual(history.map((e) => e.type), ['BookingRequested', 'BookingApproved', 'BookingStarted']);
  });

  test('ไม่พบเหตุการณ์ของการจองที่ไม่มีอยู่ -> อาร์เรย์ว่าง', () => {
    const events = [requested('bk-1', '2026-08-01T00:00:00.000Z')];
    assert.deepEqual(eventsForBooking(events, 'bk-999'), []);
  });
});

